public async Task<string> GetDataAsync(string url)
{
    while (true)
    {
        try
        {
            return await _httpClient.GetStringAsync(url);
        }
        catch
        {
            // Retries every exception, forever
            await Task.Delay(100);
        }
    }
}

var retryPolicy = Policy
    .Handle<HttpRequestException>()
    .OrResult<HttpResponseMessage>(r => (int)r.StatusCode >= 500)
    .WaitAndRetryAsync(
        retryCount: 3,
        sleepDurationProvider: attempt =>
            TimeSpan.FromSeconds(Math.Pow(2, attempt)) + TimeSpan.FromMilliseconds(Random.Shared.Next(0, 1000)),
        onRetry: (outcome, timespan, attempt, context) =>
        {
            _logger.LogWarning("Retry {Attempt} for {Url} due to {Reason}",
                attempt, context["url"], outcome.Exception?.Message ?? outcome.Result.StatusCode.ToString());
            return Task.CompletedTask;
        });

var circuitBreaker = Policy
    .Handle<HttpRequestException>()
    .OrResult<HttpResponseMessage>(r => (int)r.StatusCode >= 500)
    .CircuitBreakerAsync(
        handledEventsAllowedBeforeBreaking: 5,
        durationOfBreak: TimeSpan.FromSeconds(30));

var combined = Policy.WrapAsync(retryPolicy, circuitBreaker);

var response = await combined.ExecuteAsync(
    async ctx => await _httpClient.GetAsync(url, ctx),
    new Context { ["url"] = url });
